-- Independent historical schema transcribed from git 5e2a28d:
-- lib/core/database/tables/*.dart and app_database.g.dart (schemaVersion=4).
-- No current database schema is used to construct this fixture.
PRAGMA foreign_keys = ON;
CREATE TABLE user_profiles (sync_id TEXT NOT NULL, sync_version INTEGER NOT NULL DEFAULT 0, updated_at_utc INTEGER NOT NULL, deleted_at_utc INTEGER, id INTEGER NOT NULL DEFAULT 1 PRIMARY KEY, imie TEXT NOT NULL DEFAULT 'Robert', wiek INTEGER NOT NULL, wzrost_cm REAL NOT NULL, waga_kg REAL NOT NULL, cel TEXT NOT NULL, dostepny_sprzet TEXT NOT NULL, onboarding_zakonczony INTEGER NOT NULL DEFAULT 0 CHECK(onboarding_zakonczony IN (0,1)), data_utworzenia INTEGER NOT NULL DEFAULT (strftime('%s', CURRENT_TIMESTAMP)));
CREATE TABLE exercises (id TEXT NOT NULL PRIMARY KEY, nazwa_pl TEXT NOT NULL, nazwa_en TEXT NOT NULL, partia_glowna TEXT NOT NULL, partie_wspierajace TEXT NOT NULL, sprzet TEXT NOT NULL, typ TEXT NOT NULL, poziom TEXT NOT NULL, wzorzec_ruchu TEXT NOT NULL, seriex_powtorzenia TEXT NOT NULL, tempo TEXT NOT NULL, kluczowe_wskazowki TEXT NOT NULL, czeste_bledy TEXT NOT NULL, progresja TEXT NOT NULL, regresja TEXT NOT NULL, zrodlo TEXT NOT NULL);
CREATE TABLE workout_sessions (sync_id TEXT NOT NULL, sync_version INTEGER NOT NULL DEFAULT 0, updated_at_utc INTEGER NOT NULL, deleted_at_utc INTEGER, id INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, data_start INTEGER NOT NULL, data_koniec INTEGER, czas_trwania_sekund INTEGER NOT NULL DEFAULT 0, notatka TEXT);
CREATE TABLE sets_log (sync_id TEXT NOT NULL, sync_version INTEGER NOT NULL DEFAULT 0, updated_at_utc INTEGER NOT NULL, deleted_at_utc INTEGER, id INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, sesja_id INTEGER NOT NULL REFERENCES workout_sessions(id) ON DELETE CASCADE, cwiczenie_id TEXT NOT NULL, nazwa_cwiczenia_pl TEXT NOT NULL, numer_serii INTEGER NOT NULL, ciezar_kg REAL, powtorzenia INTEGER, czas_sekund INTEGER, rpe INTEGER, timestamp INTEGER NOT NULL DEFAULT (strftime('%s', CURRENT_TIMESTAMP)));
CREATE TABLE mood_entries (sync_id TEXT NOT NULL, sync_version INTEGER NOT NULL DEFAULT 0, updated_at_utc INTEGER NOT NULL, deleted_at_utc INTEGER, id INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, data INTEGER NOT NULL DEFAULT (strftime('%s', CURRENT_TIMESTAMP)), sn_godziny REAL NOT NULL, energia INTEGER NOT NULL, nastroj INTEGER NOT NULL, apetyt INTEGER NOT NULL, alkohol INTEGER NOT NULL DEFAULT 0 CHECK(alkohol IN (0,1)), alkohol_jednostki INTEGER NOT NULL DEFAULT 0);
CREATE TABLE measurements (sync_id TEXT NOT NULL, sync_version INTEGER NOT NULL DEFAULT 0, updated_at_utc INTEGER NOT NULL, deleted_at_utc INTEGER, id INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, data INTEGER NOT NULL DEFAULT (strftime('%s', CURRENT_TIMESTAMP)), waga_kg REAL NOT NULL, obwod_klatki REAL, obwod_talii REAL, obwod_bioder REAL, obwod_bicepsu_p REAL, obwod_bicepsu_l REAL, obwod_uda_p REAL, obwod_uda_l REAL, obwod_lydki_p REAL, obwod_lydki_l REAL, procent_tluszczu REAL, tetno_spoczynkowe INTEGER, cisnienie TEXT, notatka TEXT);
CREATE TABLE fitness_test_results (sync_id TEXT NOT NULL, sync_version INTEGER NOT NULL DEFAULT 0, updated_at_utc INTEGER NOT NULL, deleted_at_utc INTEGER, id INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, typ TEXT NOT NULL, data INTEGER NOT NULL DEFAULT (strftime('%s', CURRENT_TIMESTAMP)), wynik REAL NOT NULL, score INTEGER NOT NULL DEFAULT 0);
CREATE TABLE personal_records (sync_id TEXT NOT NULL, sync_version INTEGER NOT NULL DEFAULT 0, updated_at_utc INTEGER NOT NULL, deleted_at_utc INTEGER, id INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, cwiczenie_id TEXT NOT NULL, nazwa_cwiczenia_pl TEXT NOT NULL, ciezar_kg REAL NOT NULL, powtorzenia INTEGER NOT NULL, data INTEGER NOT NULL DEFAULT (strftime('%s', CURRENT_TIMESTAMP)), szacowane1_rm REAL NOT NULL);
CREATE TABLE workout_plans (sync_id TEXT NOT NULL, sync_version INTEGER NOT NULL DEFAULT 0, updated_at_utc INTEGER NOT NULL, deleted_at_utc INTEGER, id INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, nazwa TEXT NOT NULL, cwiczenia_ids TEXT NOT NULL, cel TEXT NOT NULL, data_utworzenia INTEGER NOT NULL DEFAULT (strftime('%s', CURRENT_TIMESTAMP)));
CREATE TABLE sync_state (id INTEGER NOT NULL DEFAULT 1 CHECK(id = 1) PRIMARY KEY, account_id TEXT NOT NULL, device_id TEXT NOT NULL, cursor INTEGER NOT NULL DEFAULT 0, offline_access INTEGER NOT NULL DEFAULT 1 CHECK(offline_access IN (0,1)));
CREATE TABLE sync_outbox (operation_id TEXT NOT NULL PRIMARY KEY, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, base_version INTEGER NOT NULL, payload_json TEXT NOT NULL, attempted INTEGER NOT NULL DEFAULT 0 CHECK(attempted IN (0,1)), preserve_local INTEGER NOT NULL DEFAULT 0 CHECK(preserve_local IN (0,1)), deleted INTEGER NOT NULL DEFAULT 0 CHECK(deleted IN (0,1)), created_at_utc INTEGER NOT NULL DEFAULT (strftime('%s', CURRENT_TIMESTAMP)));
CREATE TABLE sync_deferred_records (entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, version INTEGER NOT NULL, record_json TEXT NOT NULL, PRIMARY KEY(entity_type, entity_id));
CREATE TABLE exercise_favorites (sync_id TEXT NOT NULL, sync_version INTEGER NOT NULL DEFAULT 0, updated_at_utc INTEGER NOT NULL, deleted_at_utc INTEGER, exercise_id TEXT NOT NULL REFERENCES exercises(id) ON DELETE CASCADE PRIMARY KEY);
PRAGMA user_version = 4;
